arguments.command:
sed -i '$d' tests/book_test.sh
cat >> tests/book_test.sh <<'EOF'

# ROOM-12: overlap rules
f=$(mktemp)
BOOKINGS=$f bash bin/book A 0900 1000 standup >/dev/null
for args in "A 0930 1030" "A 0800 0901" "A 0900 1000" "A 0830 1100" "A 0930 0945"; do
  before=$(cat "$f")
  BOOKINGS=$f bash bin/book $args x >/dev/null 2>&1 && { echo "overlap accepted: $args"; fail=1; }
  [ "$(cat "$f")" = "$before" ] || { echo "file changed on overlap: $args"; fail=1; }
done
BOOKINGS=$f bash bin/book A 1000 1100 next >/dev/null || { echo "adjacent after end rejected"; fail=1; }
BOOKINGS=$f bash bin/book A 0800 0900 prev >/dev/null || { echo "adjacent before start rejected"; fail=1; }
BOOKINGS=$f bash bin/book B 0900 1000 other >/dev/null || { echo "other room rejected"; fail=1; }
[ "$(wc -l < "$f")" -eq 4 ] || { echo "line count after overlap tests"; fail=1; }
rm -f "$f"
exit $fail
EOF
bash scripts/verify.sh; echo rc=$?

